function renderDesktop(){const area=$('#desktop-files'),items=files.filter(f=>f.parent==='desktop'&&visible(f));assignDesktopPositions(items.map(f=>f.id));area.innerHTML=items.map(f=>fileCard(f,desktopSelection)).join('');for(const f of items){const el=$('[data-file="'+f.id+'"]',area);el.style.right=(f.position?.col||0)*104+12+'px';el.style.top=(f.position?.row||0)*108+10+'px'}bindFileCards(area,desktopSelection);marquee(area,desktopSelection)}
function bindDesktop(){const area=$('#desktop-files');bindDrop(area,()=> 'desktop',e=>{const ids=readDrag(e),bounds=desktopBounds();const result=moveItems(files,ids,'desktop');if(!result.ok)return toast(result.error);assignDesktopPositions(result.items.map(f=>f.id),{x:e.clientX-bounds.left,y:e.clientY-bounds.top});refreshFiles()});area.oncontextmenu=e=>{if(e.target.closest('[data-file]'))return;e.preventDefault();e.stopPropagation();showMenu(e.clientX,e.clientY,backgroundMenu('desktop'))}}
function backgroundMenu(parent,w){return [['New Folder',()=>createFile('folder',parent)],['New Document',()=>createFile('text',parent)],['Import Files…',()=>importFiles(parent)],['Paste',()=>pasteFiles(parent)],null,...(parent==='desktop'?[['Clean Up',()=>{files.filter(f=>f.parent==='desktop').forEach(f=>delete f.position);renderDesktop();save()}],['Change Wallpaper…',()=>openApp('settings')]]:[['Select All',()=>{const set=w?.selection;if(set){files.filter(f=>f.parent===parent&&visible(f)).forEach(f=>set.add(f.id));paintSelection(w.body,set)}}]])]}
function pasteFiles(parent){if(!clipboard)return toast('Copy or cut some files first.');if(parent==='root')parent='documents';if(clipboard.cut){if(moveFiles(clipboard.ids,parent))clipboard=null;return}const dest=files.find(f=>f.id===parent);if(!dest||!visible(dest))return;const selected=clipboard.ids.filter(id=>!clipboard.ids.some(other=>other!==id&&descendants(files,other).has(id)));for(const id of selected){const f=files.find(f=>f.id===id);if(!f||f.parent==='root')continue;const originals=files.filter(x=>descendants(files,id).has(x.id)),map=new Map(originals.map(x=>[x.id,uid()]));let name=f.name;while(files.some(x=>x.parent===parent&&!x.deleted&&x.name===name))name='Copy of '+name;for(const o of originals)files.push({...structuredClone(o),id:map.get(o.id),name:o.id===id?name:o.name,parent:o.id===id?parent:map.get(o.parent),position:undefined,modified:Date.now()})}refreshFiles()}
