async function readImports(list,parent){if(parent==='root')parent='documents';for(const file of Array.from(list)){if(file.size>40*1024*1024){toast(file.name+' exceeds the 40 MB limit.');continue}const detected=extensions[file.name.split('.').pop().toLowerCase()];const type=detected==='code'||detected==='text'?'text':detected|| (file.type.startsWith('image/')?'image':file.type.startsWith('audio/')?'audio':file.type.startsWith('text/')?'text':'binary');try{const content=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;type==='text'?r.readAsText(file):r.readAsDataURL(file)});let name=file.name;while(files.some(f=>f.parent===parent&&!f.deleted&&f.name===name))name='Copy of '+name;files.push({id:uid(),name,type,parent,content,mime:file.type,size:file.size,imported:true,note:false,modified:Date.now()})}catch{toast('Could not read '+file.name)}}refreshFiles();toast('Import complete')}
