function renderFiles(w){const s=w.state;s.folder??='documents';s.view??='grid';s.query??='';const current=files.find(f=>f.id===s.folder);if(s.folder!=='root'&&(!current||!visible(current)))s.folder='documents';const items=files.filter(f=>f.parent===s.folder&&visible(f)&&f.name.toLowerCase().includes(s.query.toLowerCase())).sort((a,b)=>(b.type==='folder')-(a.type==='folder')||a.name.localeCompare(b.name));w.body.innerHTML='<div class="split"><aside class="sidebar"><small>Favorites</small>'+[['root','home','Home'],...roots.map(([id,n])=>[id,id==='pictures'?'photos':id==='downloads'?'download':'folder',n])].map(([id,ic,n])=>'<button data-folder="'+id+'" class="'+(s.folder===id?'active':'')+'">'+icon(ic)+n+'</button>').join('')+'<small class="section-gap">Locations</small><button data-action="trash">'+icon('trash')+'Trash</button></aside><div class="pane"><div class="toolbar">'+button(icon('back'),'back')+'<h3>'+esc(files.find(f=>f.id===s.folder)?.name||'Home')+'</h3><span class="spacer"></span>'+button(icon('plus'),'new')+button(icon('upload'),'import')+button(icon(s.view==='grid'?'list':'grid'),'view')+'<input class="file-search" placeholder="Search" value="'+esc(s.query)+'" aria-label="Search files"></div><div class="file-grid '+s.view+'" role="listbox" aria-label="Files" aria-multiselectable="true">'+(items.map(f=>fileCard(f,w.selection)).join('')||'<div class="empty">'+icon('folder',40)+'<p>This folder is empty.</p></div>')+'</div><div class="statusbar"><span>'+items.length+' items</span><span>'+esc(folderPath(s.folder))+'</span></div></div></div>';$('.window-title',w.el).textContent=files.find(f=>f.id===s.folder)?.name||'Home';qa(w,'[data-folder]').forEach(b=>{b.onclick=()=>{s.folder=b.dataset.folder;s.query='';w.selection.clear();render(w)};if(b.dataset.folder!=='root')bindDrop(b,()=>b.dataset.folder)});bind(w,'trash',()=>openApp('trash'));bind(w,'back',()=>{s.folder=files.find(f=>f.id===s.folder)?.parent||'root';s.query='';render(w)});q(w,'[data-action="back"]').disabled=s.folder==='root';bind(w,'new',()=>createFile('folder',s.folder));bind(w,'import',()=>importFiles(s.folder));bind(w,'view',()=>{s.view=s.view==='grid'?'list':'grid';render(w)});q(w,'.file-search').oninput=e=>{const pos=e.target.selectionStart;s.query=e.target.value;render(w);const input=q(w,'.file-search');input.focus();input.setSelectionRange(pos,pos)};const area=q(w,'.file-grid');bindFileCards(area,w.selection,w);marquee(area,w.selection);bindDrop(area,()=>s.folder==='root'?'documents':s.folder);area.oncontextmenu=e=>{e.preventDefault();e.stopPropagation();showMenu(e.clientX,e.clientY,backgroundMenu(s.folder,w))};}
function folderPath(id){if(id==='root')return 'Home';const segments=[],seen=new Set();let f=files.find(f=>f.id===id);while(f&&!seen.has(f.id)){seen.add(f.id);segments.unshift(f.name);f=files.find(x=>x.id===f.parent)}return 'Home / '+segments.join(' / ')}
function renderTrash(w){const items=files.filter(f=>f.deleted);w.body.innerHTML='<div class="toolbar"><h3>Trash</h3><span class="spacer"></span>'+button('Put Back','restore')+button('Empty Trash…','empty')+'</div><div class="file-grid">'+(items.map(f=>fileCard(f,w.selection)).join('')||'<div class="empty">'+icon('trash',48)+'<p>Trash is empty.</p></div>')+'</div><div class="statusbar">'+items.length+' items</div>';bindFileCards(q(w,'.file-grid'),w.selection,w);marquee(q(w,'.file-grid'),w.selection);bind(w,'restore',()=>{for(const f of items)if(w.selection.has(f.id))f.deleted=false;refreshFiles()});bind(w,'empty',()=>purgeItems(items.map(f=>f.id)));q(w,'[data-action="empty"]').disabled=!items.length;}

