function stopSlideshow(w){clearInterval(w.state.slideshow);w.state.slideshow=null}
async function exportPhoto(f){if(!f.edits)return exportFile(f);try{const img=new Image();img.src=f.content;await img.decode();const r=f.edits.rotation||0,swap=r%180!==0,c=document.createElement('canvas');c.width=swap?img.naturalHeight:img.naturalWidth;c.height=swap?img.naturalWidth:img.naturalHeight;const ctx=c.getContext('2d');ctx.translate(c.width/2,c.height/2);ctx.rotate(r*Math.PI/180);ctx.filter='brightness('+(f.edits.brightness||1)+') saturate('+(f.edits.saturation??1)+')';ctx.drawImage(img,-img.naturalWidth/2,-img.naturalHeight/2);c.toBlob(blob=>{if(blob){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=f.name.replace(/\.[^.]+$/,'')+'-edited.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}},'image/png')}catch{toast('Unable to export the edited image.')}}
