let catalog=[],currentTrack=null,musicQueue=[],shuffle=false,repeat=false;const player=new Audio();player.preload='metadata';
async function loadCatalog(){try{const r=await fetch('assets/catalog.json');catalog=await r.json()}catch{catalog=[]}}
function fileTrack(f){return {id:f.id,title:f.name.replace(/\.[^.]+$/,''),artist:'Your Library',album:'Imported Music',src:f.content,img:'assets/icons/music.png',preview:false}}
function allTracks(){return [...catalog,...files.filter(f=>f.type==='audio'&&visible(f)).map(fileTrack)]}
function updateMusic(){for(const w of windows.values())if(w.app==='music')render(w);syncControlPlayback()}
async function playTrack(t,queue){if(!t?.src){toast('No official preview is available for this track.');return}if(queue)musicQueue=queue;else if(!musicQueue.some(x=>x.id===t.id))musicQueue=allTracks();if(currentTrack?.id===t.id){if(player.paused){try{await player.play()}catch{toast('Playback was blocked. Try again.')}}else player.pause();return}currentTrack=t;player.src=t.src;player.volume=prefs.volume;try{await player.play()}catch{toast('This preview could not be loaded. Try the full-track link.')}updateMusic()}
function nextTrack(direction=1){if(!musicQueue.length)musicQueue=allTracks();if(!musicQueue.length)return;let index=musicQueue.findIndex(t=>t.id===currentTrack?.id);index=shuffle?Math.floor(Math.random()*musicQueue.length):(index+direction+musicQueue.length)%musicQueue.length;const t=musicQueue[index];if(t.id===currentTrack?.id){player.currentTime=0;player.play().catch(()=>{})}else playTrack(t)}
player.addEventListener('play',updateMusic);player.addEventListener('pause',updateMusic);player.addEventListener('ended',()=>{if(repeat){player.currentTime=0;player.play().catch(()=>{})}else nextTrack()});player.addEventListener('error',()=>toast('Audio is unavailable. Use the full-track link or import a local file.'));
function timeLabel(t){if(!Number.isFinite(t))return '0:00';return Math.floor(t/60)+':'+String(Math.floor(t%60)).padStart(2,'0')}
player.addEventListener('timeupdate',()=>{for(const w of windows.values())if(w.app==='music'){const range=q(w,'.music-seek');if(range&&!range.matches(':active')){range.value=player.duration?player.currentTime/player.duration*100:0;paintRange(range)}const label=q(w,'.track-time');if(label)label.textContent=timeLabel(player.currentTime)+' / '+timeLabel(player.duration)}});
