function calc(w,k){const s=w.state;if(/^[0-9.]$/.test(k)){if(s.fresh||s.value==='Error'){s.value=k==='.'?'0.':k;s.fresh=false}else if(s.value.length<16&&(k!=='.'||!s.value.includes('.')))s.value=s.value==='0'&&k!=='.'?k:s.value+k}else if(k==='AC'){s.value='0';delete s.operand;delete s.operator;s.fresh=true}else if(k==='±')s.value=String(-Number(s.value));else if(k==='%')s.value=String(Number(s.value)/100);else if(k==='⌫')s.value=s.value.slice(0,-1)||'0';else{if(s.operator&&s.operand!==undefined&&!s.fresh)s.value=calculate(s.operand,Number(s.value),s.operator);s.operand=Number(s.value);s.operator=k==='='?null:k;s.fresh=true}render(w)}
