let lockAnimation;
function lock(){lockAnimation?.cancel();closePopovers();$('#search').classList.add('hidden');$('#launchpad').classList.add('hidden');const el=$('#lock');el.classList.remove('hidden');$('#unlock-form').classList.toggle('hidden',!prefs.pin);$('#unlock-direct').classList.toggle('hidden',!!prefs.pin);$('#unlock-pin').value='';$('#unlock-pin').type='password';$('#unlock-eye').setAttribute('aria-pressed','false');$('#unlock-eye').setAttribute('aria-label','Show code');$('#lock-error').textContent='';lockAnimation=el.animate([{opacity:0,transform:'scale(1.035)'},{opacity:1,transform:'scale(1)'}],{duration:motionDuration(300),easing:'cubic-bezier(.16,1,.3,1)'});clock();if(prefs.pin)$('#unlock-pin').focus();else $('#unlock-direct').focus();}
function unlock(){lockAnimation?.cancel();const el=$('#lock');const animation=el.animate([{opacity:1,transform:'scale(1)'},{opacity:0,transform:'scale(1.045) translateY(-10px)'}],{duration:motionDuration(320),easing:'cubic-bezier(.4,0,.2,1)',fill:'forwards'});lockAnimation=animation;animation.finished.then(()=>{el.classList.add('hidden');animation.cancel();$('#unlock-pin').value='';$('#unlock-pin').type='password'}).catch(()=>{});$('#windows').animate([{opacity:.55,transform:'scale(.985)'},{opacity:1,transform:'scale(1)'}],{duration:motionDuration(340),easing:'ease-out'})}
function motionDuration(ms){return prefs.reduceMotion||matchMedia('(prefers-reduced-motion: reduce)').matches?0:ms;}
function submitUnlock(){if(!prefs.pin||$('#unlock-pin').value===prefs.pin)unlock();else{$('#lock-error').textContent='Incorrect code. Try again.';$('#unlock-pin').focus();$('#unlock-pin').select();$('#unlock-form').animate([{transform:'translateX(0)'},{transform:'translateX(-6px)'},{transform:'translateX(6px)'},{transform:'translateX(0)'}],{duration:motionDuration(220)})}}
function handleLockKey(e){if($('#lock').classList.contains('hidden')||$('#dialog').open)return;const input=$('#unlock-pin');if(e.key==='Enter'&&!e.isComposing){e.preventDefault();e.stopPropagation();submitUnlock();return}if(!security.hasPin||e.ctrlKey||e.metaKey||e.altKey||e.isComposing||e.target===input)return;if(e.key.length===1){e.preventDefault();e.stopPropagation();input.focus();input.setRangeText(e.key,input.selectionStart??input.value.length,input.selectionEnd??input.value.length,'end');input.dispatchEvent(new Event('input',{bubbles:true}))}else if(e.key==='Backspace'){e.preventDefault();input.focus();const start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.setRangeText('',start===end?Math.max(0,start-1):start,end,'end');input.dispatchEvent(new Event('input',{bubbles:true}))}}
document.addEventListener('keydown',handleLockKey,true);
document.addEventListener('paste',e=>{if($('#lock').classList.contains('hidden')||!security.hasPin||e.target===$('#unlock-pin'))return;const text=e.clipboardData?.getData('text/plain');if(text){e.preventDefault();const input=$('#unlock-pin');input.focus();input.setRangeText(text,input.selectionStart??input.value.length,input.selectionEnd??input.value.length,'end');input.dispatchEvent(new Event('input',{bubbles:true}))}},true);
document.addEventListener('compositionstart',()=>{if(!$('#lock').classList.contains('hidden')&&security.hasPin)$('#unlock-pin').focus()},true);

async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('Full screen is unavailable here. Open Atelier in a browser tab and press F11.')}}
let searchActions=[],searchIndex=0;function showSearch(){if(!$('#lock').classList.contains('hidden'))return;closePopovers();$('#search').classList.remove('hidden');$('#global-search').value='';renderSearch();$('#global-search').focus()}
function renderSearch(){const query=$('#global-search').value.toLowerCase();searchActions=[];let html='';Object.entries(appNames).filter(([id,n])=>n.toLowerCase().includes(query)).forEach(([id,n])=>{searchActions.push(()=>openApp(id));html+='<button data-result="'+(searchActions.length-1)+'">'+appIcon(id)+'<span>'+n+'</span></button>'});if(query)files.filter(f=>visible(f)&&f.name.toLowerCase().includes(query)).slice(0,15).forEach(f=>{searchActions.push(()=>openFile(f));html+='<button data-result="'+(searchActions.length-1)+'">'+icon(f.type==='folder'?'folder':'file')+'<span>'+esc(f.name)+'</span></button>'});$('#search-results').innerHTML=html||'<div class="empty">No results</div>';searchIndex=0;highlightSearch();$$('[data-result]').forEach(b=>b.onclick=()=>{searchActions[+b.dataset.result]();$('#search').classList.add('hidden')})}
function highlightSearch(){$$('[data-result]').forEach((b,i)=>b.classList.toggle('active',i===searchIndex))}
function selectedScope(){return activeWindow&&['files','trash'].includes(activeWindow.app)?{selection:activeWindow.selection,area:activeWindow.body,parent:activeWindow.state.folder||'documents'}:{selection:desktopSelection,area:$('#desktop-files'),parent:'desktop'}}
document.addEventListener('pointerdown',e=>{if(!e.target.closest('.popover,#menubar'))closePopovers()});document.addEventListener('contextmenu',e=>{e.preventDefault();if(e.target.closest('input:not([type=range]),textarea')){const input=e.target;if(!['text','search','password','email','tel','url'].includes(input.type)&&input.tagName!=='TEXTAREA')return;const replace=text=>{input.setRangeText(text,input.selectionStart,input.selectionEnd,'end');input.dispatchEvent(new Event('input',{bubbles:true}))};showMenu(e.clientX,e.clientY,[['Select All',()=>{input.focus();input.select()}],['Copy',async()=>{try{await navigator.clipboard.writeText(input.value.slice(input.selectionStart,input.selectionEnd))}catch{toast('Use Ctrl+C to copy.')}}],['Cut',async()=>{try{await navigator.clipboard.writeText(input.value.slice(input.selectionStart,input.selectionEnd));replace('')}catch{toast('Use Ctrl+X to cut.')}}],['Paste',async()=>{try{replace(await navigator.clipboard.readText())}catch{toast('Use Ctrl+V to paste.')}}]])}});
$('#system-menu').onclick=()=>showMenu(10,35,[['System Settings…',()=>openApp('settings')],['Search…',showSearch,'Ctrl Space'],['All Applications',showLaunchpad],null,['Enter Full Screen',fullscreen],['Lock Screen',lock,'Ctrl Alt L']]);
$$('[data-menu]').forEach(b=>b.onclick=()=>{const w=activeWindow,scope=selectedScope();let items=b.dataset.menu==='file'?[['New Window',()=>openApp(w?.app||'files',true)],['New Folder',()=>createFile('folder',scope.parent)],['New Document',()=>createFile('text',scope.parent)],['Import…',()=>importFiles(scope.parent)]]:b.dataset.menu==='view'?[['As Icons',()=>{const target=w?.app==='files'?w:openApp('files');target.state.view='grid';render(target)}],['As List',()=>{const target=w?.app==='files'?w:openApp('files');target.state.view='list';render(target)}],['Full Screen',fullscreen]]:[...windows.values()].map(win=>[(win.minimized?'Restore ':'')+appNames[win.app]+' — '+(win.app==='files'?folderPath(win.state.folder):win.id.slice(0,4)),()=>focusWindow(win)]);if(!items.length)items=[['New Finder Window',()=>openApp('files',true)]];showMenu(b.getBoundingClientRect().left,35,items)});
$('#full-btn').innerHTML=icon('fullscreen',17);$('#full-btn').onclick=fullscreen;$('#search-btn').innerHTML=icon('search',15);$('#control-btn').innerHTML=icon('control',17);$('#search-btn').onclick=showSearch;
$('#control-btn').onclick=()=>{const c=$('#control');c.classList.toggle('hidden');if(!c.classList.contains('hidden'))renderControlCenter()};
$('#clock').onclick=lock;$('#unlock-direct').onclick=unlock;$('#unlock-form').onsubmit=e=>{e.preventDefault();submitUnlock()};$('#unlock-eye').innerHTML=icon('eye',17);$('#unlock-eye').onclick=()=>{const input=$('#unlock-pin'),show=input.type==='password',start=input.selectionStart,end=input.selectionEnd;input.type=show?'text':'password';$('#unlock-eye').setAttribute('aria-pressed',String(show));$('#unlock-eye').setAttribute('aria-label',show?'Hide code':'Show code');input.focus();input.setSelectionRange(start,end)};
$('#global-search').oninput=renderSearch;$('#global-search').onkeydown=e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();searchIndex=(searchIndex+(e.key==='ArrowDown'?1:-1)+searchActions.length)%Math.max(1,searchActions.length);highlightSearch()}if(e.key==='Enter'&&searchActions[searchIndex]){searchActions[searchIndex]();$('#search').classList.add('hidden')}};$('#search').onclick=e=>{if(e.target===$('#search'))$('#search').classList.add('hidden')};$('#launch-search').oninput=e=>renderLaunchpad(e.target.value);$('#launchpad').onclick=e=>{if(e.target===$('#launchpad'))$('#launchpad').classList.add('hidden')};$('#importer').onchange=e=>{readImports(Array.from(e.target.files),importParent);e.target.value=''};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closePopovers();$('#search').classList.add('hidden');$('#launchpad').classList.add('hidden')}if(!$('#lock').classList.contains('hidden')||$('#dialog').open)return;const mod=e.ctrlKey||e.metaKey;if(mod&&e.code==='Space'){e.preventDefault();showSearch();return}if(e.ctrlKey&&e.altKey&&e.key.toLowerCase()==='l'){e.preventDefault();lock();return}if(e.target.closest('input,textarea,[contenteditable]'))return;if(activeWindow?.app==='calculator'){const k=({Enter:'=',Backspace:'⌫','*':'×','/':'÷','-':'−',',':'.',Escape:'AC'})[e.key]||e.key;if(/^[0-9.+%=÷×−]$/.test(k)||['AC','⌫'].includes(k)){e.preventDefault();calc(activeWindow,k);return}}if(activeWindow&&!['files','trash'].includes(activeWindow.app)){if(mod&&e.key.toLowerCase()==='n'){e.preventDefault();openApp(activeWindow.app,true)}return}const scope=selectedScope();if(mod&&e.key.toLowerCase()==='a'){e.preventDefault();$$('[data-file]',scope.area).forEach(el=>scope.selection.add(el.dataset.file));paintSelection(scope.area,scope.selection)}if(mod&&['c','x'].includes(e.key.toLowerCase())){e.preventDefault();clipboard={ids:[...scope.selection],cut:e.key.toLowerCase()==='x'};toast(scope.selection.size+' item(s) '+(clipboard.cut?'ready to move':'copied'))}if(mod&&e.key.toLowerCase()==='v'){e.preventDefault();pasteFiles(scope.parent)}if(e.key==='Delete'||e.key==='Backspace'){if(scope.selection.size){e.preventDefault();if(activeWindow?.app==='trash')purgeItems([...scope.selection]);else trashItems([...scope.selection]);scope.selection.clear()}}if(mod&&e.key.toLowerCase()==='n'){e.preventDefault();openApp(activeWindow?.app||'files',true)}});
window.addEventListener('resize',()=>{for(const w of windows.values()){if(w.maximized){w.el.style.width=innerWidth+'px';w.el.style.height=innerHeight+'px'}else{const width=Math.min(parseFloat(w.el.style.width),innerWidth-16),height=Math.min(parseFloat(w.el.style.height),innerHeight-100);Object.assign(w.el.style,{width:width+'px',height:height+'px',left:Math.max(96-width,Math.min(parseFloat(w.el.style.left),innerWidth-96))+'px',top:Math.max(32,Math.min(parseFloat(w.el.style.top),innerHeight-height-70))+'px'})}}renderDesktop()});

let saveTimer;
function scheduleSave(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>save(),180)}
function paintRange(input){input.style.setProperty('--range-progress',((+input.value-(+input.min||0))/(+input.max-(+input.min||0))*100)+'%')}
function paintRanges(root=document){root.querySelectorAll('input[type=range]').forEach(paintRange)}
document.addEventListener('input',e=>{if(e.target.matches('input[type=range]'))paintRange(e.target)});
function resizePhotoGrid(w,size){w.state.zoom=size;paintRange(q(w,'.photo-size'));if(w.photoResizeFrame)return;w.photoResizeFrame=requestAnimationFrame(()=>{w.photoResizeFrame=null;if(!windows.has(w.id))return;const grid=q(w,'.photo-grid');if(!grid)return;const bounds=q(w,'.gallery').getBoundingClientRect();const cards=[...grid.children].filter(c=>{const r=c.getBoundingClientRect();return r.bottom>bounds.top-200&&r.top<bounds.bottom+200}).slice(0,80);const before=cards.map(c=>c.getBoundingClientRect());cards.forEach(c=>c.layoutAnimation?.cancel());grid.style.gridTemplateColumns='repeat(auto-fill,minmax('+w.state.zoom+'px,1fr))';if(!motionDuration(180))return;cards.forEach((c,i)=>{const a=before[i],b=c.getBoundingClientRect();if(!b.width||!b.height)return;c.layoutAnimation=c.animate([{transform:'translate('+(a.left-b.left)+'px,'+(a.top-b.top)+'px) scale('+a.width/b.width+','+a.height/b.height+')'},{transform:'none'}],{duration:180,easing:'cubic-bezier(.2,.8,.2,1)'})})})}
function renderControlCenter(){const c=$('#control');c.innerHTML='<div class="cc-heading">Control Center<button class="cc-settings" aria-label="Open Settings">'+icon('settings',17)+'</button></div><div class="cc-tiles"><button class="cc-tile cc-theme">'+icon('moon',19)+'<span>Appearance<small></small></span></button><button class="cc-tile cc-fullscreen">'+icon('fullscreen',19)+'<span>Full Screen<small></small></span></button></div><div class="cc-panel"><label>Display</label><div class="cc-slider">'+icon('sun',18)+'<input type="range" data-control="brightness" min=".4" max="1" step=".01" value="'+prefs.brightness+'" aria-label="Brightness"></div></div><div class="cc-panel"><label>Sound<button class="cc-mute">Mute</button></label><div class="cc-slider">'+icon('volume',18)+'<input type="range" data-control="volume" min="0" max="1" step=".01" value="'+prefs.volume+'" aria-label="Volume"></div></div><div class="cc-panel cc-media"><img class="cc-art" alt=""><div class="cc-track"><b></b><small></small></div><button class="cc-play" aria-label="Play"></button><button class="cc-next" aria-label="Next track">'+icon('forward',18)+'</button></div><div class="cc-footer"><button class="cc-lock">'+icon('lock',15)+' Lock Screen</button><span>'+esc(prefs.name)+'</span></div>';
const theme=()=>{$('.cc-theme small',c).textContent=prefs.theme==='dark'?'Dark':'Light';$('.cc-theme',c).classList.toggle('on',prefs.theme==='dark')};theme();$('.cc-theme',c).onclick=()=>{prefs.theme=prefs.theme==='dark'?'light':'dark';applyPrefs();save();theme()};$('.cc-fullscreen',c).onclick=fullscreen;syncFullscreenControl();$('.cc-settings',c).onclick=()=>{closePopovers();openApp('settings')};$('.cc-lock',c).onclick=lock;$$('[data-control]',c).forEach(input=>input.oninput=()=>{prefs[input.dataset.control]=+input.value;applyPrefs();paintRange(input);scheduleSave();$('.cc-mute',c).textContent=prefs.volume?'Mute':'Unmute'});$('.cc-mute',c).onclick=()=>{if(prefs.volume){prefs.unmuteVolume=prefs.volume;prefs.volume=0}else prefs.volume=prefs.unmuteVolume||.5;applyPrefs();save();const input=$('[data-control=volume]',c);input.value=prefs.volume;paintRange(input);$('.cc-mute',c).textContent=prefs.volume?'Mute':'Unmute'};$('.cc-play',c).onclick=()=>{const t=currentTrack||allTracks()[0];if(t)playTrack(t)};$('.cc-next',c).onclick=()=>nextTrack();paintRanges(c);syncControlPlayback()}
function syncFullscreenControl(){const b=$('.cc-fullscreen');if(b){b.classList.toggle('on',!!document.fullscreenElement);$('small',b).textContent=document.fullscreenElement?'On':'Off'}}
document.addEventListener('fullscreenchange',syncFullscreenControl);
function syncControlPlayback(){const c=$('#control');if(!$('.cc-media',c))return;const t=currentTrack||allTracks()[0];$('.cc-track b',c).textContent=t?.title||'Music';$('.cc-track small',c).textContent=t?.artist||'Import music to play';const img=$('.cc-art',c);img.hidden=!t?.img;if(t?.img&&img.getAttribute('src')!==t.img)img.src=t.img;$('.cc-play',c).innerHTML=icon(player.paused?'play':'pause',18);$('.cc-play',c).setAttribute('aria-label',player.paused?'Play':'Pause');$('.cc-play',c).disabled=!t;$('.cc-next',c).disabled=!t}
function addLockWallpaperSettings(w){const main=q(w,'.settings-main');const group=document.createElement('section');group.innerHTML='<h3>Lock Screen Wallpaper</h3><div class="setting-row"><label for="sync-'+w.id+'">Use desktop wallpaper</label><input id="sync-'+w.id+'" class="switch" type="checkbox" role="switch" data-same-wall '+(prefs.lockSameWallpaper?'checked':'')+'></div>'+(prefs.lockSameWallpaper?'':'<div class="wallpapers">'+['wallpaper.jpg','coast.jpg','forest.jpg','dunes.jpg','dawn.svg','dusk.svg'].map(n=>'<button data-lockwall="assets/'+n+'" aria-label="'+n.split('.')[0]+' lock wallpaper" class="'+(prefs.lockWall==='assets/'+n?'active':'')+'" style="background-image:url(assets/'+n+')"></button>').join('')+'</div>');main.insertBefore(group,q(w,'.settings-footnote'));q(w,'[data-same-wall]').onchange=e=>{if(!prefs.lockWall)prefs.lockWall=prefs.wall;prefs.lockSameWallpaper=e.target.checked;applyPrefs();save();render(w)};qa(w,'[data-lockwall]').forEach(b=>b.onclick=()=>{prefs.lockWall=b.dataset.lockwall;applyPrefs();save();render(w)})}

